+// Preference Profile Module
+// Node ESM stdlib only
+
+import { readFileSync, writeFileSync, dirname } from 'node:fs/promises';
+import { randomUUID } from 'node:crypto';
+import { resolve } from 'node:path';
+
+export function createPreferenceProfile(filePath, { defaults = {} } = {}) {
+  // Ensure defaults are plain JSON-safe objects with recursively sorted keys
+  const canonicalDefaults = normalizeObject(defaults);
+
+  // Load persisted profile from file
+  let persistedProfile = null;
+  try {
+    const fileContent = await readFileSync(filePath, 'utf-8');
+    persistedProfile = JSON.parse(fileContent);
+    // Validate persisted profile
+    if (!isValidProfile(persistedProfile)) {
+      throw new Error('STATE_CORRUPT');
+    }
+  } catch (e) {
+    // If file doesn't exist or is corrupt, use defaults
+    persistedProfile = canonicalDefaults;
+  }
+
+  // Return frozen async API
+  return Object.freeze({
+    get: async () => {
+      // Return deep clone of current effective profile
+      return deepClone(persistedProfile);
+    },
+    patch: async (patchData) => {
+      // Validate patch data
+      if (!isValidProfile(patchData)) {
+        throw new Error('INVALID_PROFILE');
+      }
+
+      // Deep merge patch data onto current profile
+      const newProfile = deepMerge(persistedProfile, patchData);
+
+      // Persist canonical exact JSON
+      try {
+        await writeFileSync(filePath, JSON.stringify(newProfile, null, 0), 'utf-8');
+      } catch (e) {
+        throw new Error('STATE_CORRUPT');
+      }
+
+      // Reload persisted profile
+      persistedProfile = newProfile;
+      return deepClone(persistedProfile);
+    },
+    replace: async (newProfile) => {
+      // Validate new profile
+      if (!isValidProfile(newProfile)) {
+        throw new Error('INVALID_PROFILE');
+      }
+
+      // Persist canonical exact JSON
+      try {
+        await writeFileSync(filePath, JSON.stringify(newProfile, null, 0), 'utf-8');
+      } catch (e) {
+        throw new Error('STATE_CORRUPT');
+      }
+
+      // Reload persisted profile
+      persistedProfile = newProfile;
+      return deepClone(persistedProfile);
+    },
+    reset: async () => {
+      // Validate existing file
+      try {
+        const fileContent = await readFileSync(filePath, 'utf-8');
+        const fileProfile = JSON.parse(fileContent);
+        if (!isValidProfile(fileProfile)) {
+          throw new Error('STATE_CORRUPT');
+        }
+      } catch (e) {
+        // If file doesn't exist or is corrupt, use defaults
+        persistedProfile = canonicalDefaults;
+      }
+
+      // Persist canonical defaults
+      try {
+        await writeFileSync(filePath, JSON.stringify(canonicalDefaults, null, 0), 'utf-8');
+      } catch (e) {
+        throw new Error('STATE_CORRUPT');
+      }
+
+      // Reload persisted profile
+      persistedProfile = canonicalDefaults;
+      return deepClone(persistedProfile);
+    }
+  });
+}
+
+// Helper functions
+function normalizeObject(obj) {
+  if (!obj || typeof obj !== 'object') return obj;
+  const normalized = {};
+  Object.keys(obj).sort().forEach(key => {
+    normalized[key] = normalizeObject(obj[key]);
+  });
+  return normalized;
+}
+
+function isValidProfile(profile) {
+  if (!profile || typeof profile !== 'object') return false;
+  for (const key in profile) {
+    if (key === '__proto__' || key === 'prototype' || key === 'constructor') {
+      return false;
+    }
+    if (typeof profile[key] !== 'object' || profile[key] === null) continue;
+    if (!isValidProfile(profile[key])) return false;
+  }
+  return true;
+}
+
+function deepClone(obj) {
+  if (!obj || typeof obj !== 'object') return obj;
+  const clone = {};
+  Object.keys(obj).sort().forEach(key => {
+    clone[key] = deepClone(obj[key]);
+  });
+  return clone;
+}
+
+function deepMerge(target, source) {
+  if (!target || typeof target !== 'object') return source;
+  if (!source || typeof source !== 'object') return target;
+  const merged = {};
+  Object.keys(target).sort().forEach(key => {
+    merged[key] = deepMerge(target[key], source[key]);
+  });
+  Object.keys(source).sort().forEach(key => {
+    if (!merged[key]) merged[key] = source[key];
+  });
+  return merged;
+}

